<?php
// Conexão com o banco de dados
require 'db_connect.php';

// Função para criar uma cláusula IN segura
function createInClause($column, $values, $conn, &$types, &$params) {
    if (empty($values)) {
        return "1"; // Sempre verdadeiro se não houver valores
    }
    $placeholders = implode(',', array_fill(0, count($values), '?'));
    $types .= str_repeat('s', count($values));
    foreach ($values as $value) {
        $params[] = $value;
    }
    return "$column IN ($placeholders)";
}

// Buscar GREs
$gres = $conn->query("SELECT DISTINCT gre FROM turmas WHERE gre LIKE 'GRE%' ORDER BY gre");

// Inicializar variáveis
$escolas = null;
$professores = null;
$turmas = null;
$turma_info = [];

// Preparar a consulta para escolas se GREs forem selecionados
if (isset($_GET['gre']) && !empty($_GET['gre'])) {
    $selected_gres = $_GET['gre'];
    // Criar cláusula IN para GREs
    $types = '';
    $params = [];
    $gre_clause = createInClause('gre', $selected_gres, $conn, $types, $params);
    $stmt = $conn->prepare("SELECT DISTINCT escola FROM turmas WHERE $gre_clause ORDER BY escola");
    if ($stmt === false) {
        die("Erro na preparação da consulta: " . htmlspecialchars($conn->error, ENT_QUOTES, 'UTF-8'));
    }
    if ($gre_clause !== "1") {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $escolas = $stmt->get_result();
    $stmt->close();
}

// Preparar a consulta para professores e turmas se escolas forem selecionadas
if (isset($_GET['escola']) && !empty($_GET['escola'])) {
    $selected_escolas = $_GET['escola'];
    // Criar cláusula IN para escolas
    $types = '';
