    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 3A: Gerando rTalesHash.txt (Todos os arquivos)..." << std::endl;
    std::ofstream allHashFile("rTalesHash.txt");
    if (allHashFile.is_open()) {
        for (const auto& pair : fileHashes) {
            allHashFile << "\"" << pair.first << "\" : " << pair.second << std::endl;
        }
        allHashFile.close();
        std::cout << "Arquivo rTalesHash.txt criado com sucesso." << std::endl;
    } else {
        std::cerr << "ERRO: Não foi possível abrir rTalesHash.txt para escrita." << std::endl;
    }


    // ===============================================================
    // PASSO 3B: GERAR rTales.ini (Apenas os selecionados)
    // ===============================================================
    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 3B: Gerando rTales.ini (Arquivos selecionados)..." << std::endl;
    std::ofstream iniFile("rTales.ini");
    if (!iniFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo rTales.ini!" << std::endl;
        return 1;
    }

    for (int indexValue : selectedIndices) {
        if (indexValue > 0 && indexValue <= fileHashes.size()) {
            // Como o mapa está ordenado por nome, precisamos encontrar o item correto baseado no índice
            auto it = fileHashes.begin();
            std::advance(it, indexValue - 1); // Move o iterator para o índice desejado

            iniFile << "\"" << it->first << "\" : " << it->second << std::endl;
        }
    }
    iniFile.close();
    std::cout << "Arquivo rTales.ini criado com sucesso, contendo apenas os arquivos selecionados." << std::endl;
    std::cout << "===================================================" << std::endl;

    return 0;
}
